; Receiver for Learned from capture.json: pulse width, 25 bits per frame
; Generated by escgen (receive side) from learned_on_chip.yaml:
; every mark and space measured edge to edge and checked against its window.
; Host: PUSH one word per packet, the word the transmitter would be given.
; It queues no events: escert has nothing to refuse.

.default CTX, 0
.default CLK_KHZ, 25000                ; core clock in kHz
.default PIN, 0
.default IDLE, 0                     ; the line's level between packets
.default TOL, 25                     ; percent either way
.default SLACK_US, 60
.equ RX, 1 << PIN
.equ MARK, RX * (1 - IDLE)
.equ SPACE, RX * IDLE
.equ SLACK, CLK_KHZ * SLACK_US // 1000
.equ H0, CLK_KHZ * 7250 // 25000
.equ H1, CLK_KHZ * 23000 // 25000
.equ T, CLK_KHZ * 31500 // 25000
.equ GAP, CLK_KHZ * 229950 // 25000
.equ TOUT, ((H1 - H0) + (T - H1)) * (100 + TOL) // 100 + SLACK + 64   ; longer than any run
.assert TOUT < 0x1000000, a run too long for one wait
.equ U, (TOUT > 0xFFFF) + (TOUT > 0x1FFFF) + (TOUT > 0x3FFFF) + (TOUT > 0x7FFFF) + (TOUT > 0xFFFFF) + (TOUT > 0x1FFFFF) + (TOUT > 0x3FFFFF) + (TOUT > 0x7FFFFF) + (TOUT > 0xFFFFFF)   ; 2^U-tick units: TOUT fits 16 bits
.equ W1_T, (H0)
.equ W1_LO, ((W1_T) * (100 - TOL) // 100 - SLACK) >> U
.equ W1_HI, (((W1_T) * (100 + TOL) // 100 + SLACK) >> U) + 1
.equ W2_T, (H0) + (H1 - H0)
.equ W2_LO, ((W2_T) * (100 - TOL) // 100 - SLACK) >> U
.equ W2_HI, (((W2_T) * (100 + TOL) // 100 + SLACK) >> U) + 1
.equ W3_T, (H1 - H0) + (T - H1)
.equ W3_LO, ((W3_T) * (100 - TOL) // 100 - SLACK) >> U
.equ W3_HI, (((W3_T) * (100 + TOL) // 100 + SLACK) >> U) + 1
.equ W4_T, (T - H1)
.equ W4_LO, ((W4_T) * (100 - TOL) // 100 - SLACK) >> U
.equ W4_HI, (((W4_T) * (100 + TOL) // 100 + SLACK) >> U) + 1
.assert (W1_T) * (100 + TOL) // 100 + SLACK < TOUT, the timeout covers W1
.assert (W2_T) * (100 + TOL) // 100 + SLACK < TOUT, the timeout covers W2
.assert (W3_T) * (100 + TOL) // 100 + SLACK < TOUT, the timeout covers W3
.assert (W4_T) * (100 + TOL) // 100 + SLACK < TOUT, the timeout covers W4
.assert (W1_HI <= W2_LO) | (W2_HI <= W1_LO), W1 and W2 cannot be confused

.entry CTX, main

main:
resync:
    RDTIME r2                         ; wait for the line to idle
    SETT  r2
    ADDT  0xFFFFFF
    WAITP RX, SPACE
    JNZ   resync
idle:
    RDTIME r2                         ; wait for a packet's first mark
    SETT  r2
    ADDT  0xFFFFFF
    WAITP RX, MARK
    JNZ   idle
    RDTIME r2                         ; its start (two instructions after WAITP, as in meas)
    MOVI  r1, 0
    LDLC  24                          ; 25 bits, LSB first
bit1:
    SHR   r1, 1                       ; the next bit, 0 until a run says 1
    CALL  end_mark                    ; this run decides the bit
    CMPI  r0, W1_LO
    JC    not0_2
    CMPI  r0, W1_HI
    JC    got3                        ; a 0
not0_2:
    CMPI  r0, W2_LO
    JC    resync
    CMPI  r0, W2_HI
    JNC   resync                      ; fits neither symbol
    MOVI  r3, 0                       ; a 1
    MOVHI r3, 0x8000
    OR    r1, r3
got3:
    CALL  end_space
    CMPI  r0, W3_LO
    JC    try5
    CMPI  r0, W3_HI
    JC    ok4
try5:
    CMPI  r0, W4_LO
    JC    try6
    CMPI  r0, W4_HI
    JC    ok4
try6:
    JMP   resync                      ; fits neither symbol
ok4:
    DJNZ  bit1
    SHR   r1, 1                       ; the next bit, 0 until a run says 1
    CALL  end_mark                    ; this run decides the bit
    CMPI  r0, W1_LO
    JC    not0_7
    CMPI  r0, W1_HI
    JC    got8                        ; a 0
not0_7:
    CMPI  r0, W2_LO
    JC    resync
    CMPI  r0, W2_HI
    JNC   resync                      ; fits neither symbol
    MOVI  r3, 0                       ; a 1
    MOVHI r3, 0x8000
    OR    r1, r3
got8:
    SHR   r1, 7                       ; the first bit to bit 0
    PUSH  r1                          ; the word
    JMP   idle

; ---- end_mark / end_space: the run that began at the edge in r2 ends;
; r0 = its length in 2^U-tick units, r2 = the edge that ended it.
end_mark:
    SETT  r2
    ADDT  TOUT
    WAITP RX, SPACE
    JMP   meas
end_space:
    SETT  r2
    ADDT  TOUT
    WAITP RX, MARK
    JMP   meas
meas:
    RDTIME r0
    MOV   r3, r0
    SUB   r0, r2
    MOV   r2, r3
    SHR   r0, U
    RET
